from sworldmodel.semantic_runtime.trajectory import run_trajectory
from test_semantic_runtime import (FINAL_MARKER, NO_AT_CUTOFF, NOTHING, SCENE,
                                   UNRESOLVED, build, reviewed)


def terminal_roles(user, system):
    if "read-only outcome judge" in system \
            or "whether a stated condition has been met" in system:
        return json.dumps(NO_AT_CUTOFF if FINAL_MARKER in user
                          else UNRESOLVED), {}
    return None


turn = {"n": 0}


def transport(system, user):
    t = terminal_roles(user, system)
    if t:
        return t
    if "You are the world" in system:
        if "attempts: Post the letter" in user:
            return json.dumps({
                "judgment": "she gets to the postbox on Wednesday.",
                "event": {"description": "Ada posts the letter.",
                          "for": ["bo_ferrer"], "observed": False,
                          "after": "2 days", "by": "ada_vance",
                          "lasts": "5 minutes"}, "wakes": []}), {}
        if "attempts: Ring the office" in user:
            return json.dumps({
                "judgment": "she rings them straight away.",
                "event": {"description": "Ada rings the office.",
                          "for": ["bo_ferrer"], "observed": False,
                          "after": "0 seconds", "by": "ada_vance",
                          "lasts": "2 minutes"}, "wakes": []}), {}
        return json.dumps({"judgment": "nothing follows.", "event": None,
                           "wakes": []}), {}
    if "ada_vance" in user:
        turn["n"] += 1
        if turn["n"] == 1:
            return json.dumps({
                "decision": "I'll post it Wednesday.",
                "intentions": ["Post the letter."], "private_updates": [],
                "next_wake": {"after": "1 hour",
                              "reason": "ring the office about the boiler"}}), {}
        if turn["n"] == 2:
            return json.dumps({
                "decision": "Now I'll ring the office.",
                "intentions": ["Ring the office."], "private_updates": [],
                "next_wake": None}), {}
    return json.dumps(NOTHING), {}


world, journal, bindings = build()
trace = Trace()
run_trajectory(world, journal, bindings, SCENE["resolution"],
               RuntimeCaller(transport=reviewed(transport)),
               max_steps=30, trace=trace)
print("COMMITTED")
for e in journal.events():
    print(f"  [{e['t']}] {e['description']}  (lasts={e['lasts']})")
print("\nwaited_until_free (code deciding she was occupied):")
for w in trace.of("waited_until_free"):
    print(f"  at t={w['t']} -> free_at={w['free_at']}  {w['description']!r}")
print("\nordered_after_earlier_attempt (the intra-turn floor -- not involved):")
print("  ", trace.of("ordered_after_earlier_attempt"))

