--- SCRIPT f2_by_null_bypasses_occupancy.py ---
"""F2: the whole occupancy model is keyed on `by`, and `by: null` is legal
on an actor_intention adjudication.  So the world can put a person on a
30-minute call and the runtime neither blocks their next act nor treats
them as mid-task."""
import json, sys
sys.path.insert(0, "tests")

from sworldmodel.semantic_runtime.llm import RuntimeCaller
from sworldmodel.semantic_runtime.trace import Trace
from sworldmodel.semantic_runtime.trajectory import run_trajectory
from sworldmodel.simclock import parse_iso
from test_semantic_runtime import (FINAL_MARKER, NO_AT_CUTOFF, NOTHING, SCENE,
                                   UNRESOLVED, build, reviewed)


def terminal_roles(user, system):
    if "read-only outcome judge" in system \
            or "whether a stated condition has been met" in system:
        return json.dumps(NO_AT_CUTOFF if FINAL_MARKER in user
                          else UNRESOLVED), {}
    return None


def busy_world(by):
    """Exactly tests/test_runtime_completion.py::busy_world, except that the
    world writes `by` as given."""
    state = {"n": 0}

    def transport(system, user):
        t = terminal_roles(user, system)
        if t:
            return t
        if "You are the world" in system:
            if "attempts" not in user:
                return json.dumps({"judgment": "the scene begins.",
                                   "event": None, "wakes": []}), {}
            state["n"] += 1
            if state["n"] == 1:
                return json.dumps({
                    "judgment": "she gets him on the phone.",
                    "event": {"description": "Ada talks to Bo on the phone.",
                              "for": ["bo_ferrer"], "observed": True,
                              "after": "0 seconds", "by": by,
                              "lasts": "30 minutes"}, "wakes": []}), {}
            if state["n"] == 2:
                return json.dumps({
                    "judgment": "she also gets the papers away.",
                    "event": {"description": "Ada posts the signed papers.",
                              "for": ["bo_ferrer"], "observed": False,
                              "after": "2 minutes", "by": by,
                              "lasts": "0 seconds"}, "wakes": []}), {}
            return json.dumps({"judgment": "nothing further.",
                               "event": None, "wakes": []}), {}
        if "ada_vance" in user and state["n"] == 0:
            return json.dumps({
                "decision": "I will call him and send the papers.",
                "intentions": ["call Bo", "post the signed papers"],
                "private_updates": []}), {}
        return json.dumps(NOTHING), {}
    return transport


for by in ("ada_vance", None):
    world, journal, bindings = build()
    trace = Trace()
    caller = RuntimeCaller(transport=reviewed(busy_world(by)))
    run_trajectory(world, journal, bindings, SCENE["resolution"], caller,
                   max_steps=20, trace=trace)
    at = {e["description"]: parse_iso(e["t"]) for e in journal.events()}
    call = at.get("Ada talks to Bo on the phone.")
    post = at.get("Ada posts the signed papers.")
    gap = (post - call).total_seconds() if call and post else None
    print(f"by={by!r:12} second act begins {gap}s into a 30-minute call "
          f"(1800 required); still_mid_task fired "
          f"{len(trace.of('still_mid_task'))} times")

